const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul'}).format(new Date()),dt=()=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric',weekday:'short'}).format(new Date()),timeFmt=x=>x?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(x)):'—';
const app=$('#app');let user=null,chartInstances=[];const demo=location.hostname==='localhost'||location.hostname==='127.0.0.1';
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
async function api(path,options={}){let csrf=window.__csrf||'';if(!csrf&&options.method&&options.method!=='GET'&&path!=='/auth/login'&&path!=='/auth/signup'){try{const me=await fetch('/api/auth/me',{credentials:'same-origin'});if(me.ok){const data=await me.json();window.__csrf=csrf=data.csrf||''}}catch{}}if(path==='/auth/login'&&options.body){try{const credentials=JSON.parse(options.body);credentials.returnTo=safeVerifyReturn(sessionStorage.getItem('fp_pending_verify'));options={...options,body:JSON.stringify(credentials)}}catch{}}let r;try{r=await fetch('/api'+path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{}),...(options.headers||{})},...options})}catch{throw Object.assign(new Error('서버에 연결할 수 없습니다. 네트워크 상태를 확인해 주세요.'),{status:0})}let d;try{d=await r.json()}catch{d={error:`서버가 올바르지 않은 응답을 반환했습니다. (HTTP ${r.status})`}}if(path==='/auth/me'&&r.ok&&d.csrf)window.__csrf=d.csrf;if(!r.ok)throw Object.assign(new Error(d.error||`요청에 실패했습니다. (HTTP ${r.status})`),{status:r.status,body:d});return d}
function logo(){return `<a class="brand" href="/"><span class="brand-mark">F</span><span class="brand-name">FactoryPass</span></a>`}
function safeVerifyReturn(value){if(typeof value!=='string'||value.length>256)return null;try{const candidate=new URL(value,location.origin);if(candidate.origin!==location.origin||candidate.pathname!=='/employee/verify'||candidate.search)return null;const token=new URLSearchParams(candidate.hash.slice(1)).get('t');if(!/^[a-f\d]{64}$/i.test(token||''))return null;return `/employee/verify#t=${token}`}catch{return null}}
function landing(){app.innerHTML=`<nav class="landing-nav"><div class="nav-inner">${logo()}<div class="nav-links" id="nav-links"><a href="#features">서비스 소개</a><a href="#features">주요 기능</a><a href="#steps">이용 방법</a></div><div class="nav-actions"><a class="btn" href="/login">로그인</a><a class="btn btn-primary" href="/signup">근로자 회원가입</a><button class="menu-toggle" id="menu-toggle" aria-label="메뉴">☰</button></div></div></nav><main><section class="hero"><div><div class="eyebrow">SMART ATTENDANCE FOR MODERN FACTORY</div><h1>QR코드 하나로 완성하는<br><em>스마트 근태관리</em></h1><p class="hero-copy">복잡한 출퇴근 기록은 이제 그만. FactoryPass로 간편하게 출퇴근하고 효율적으로 근태를 관리하세요.</p><div class="hero-actions"><a class="btn btn-primary" href="/login">로그인하고 시작하기 <span>→</span></a><a class="btn" href="/signup">근로자 회원가입</a></div><p class="trust-line">회사 구성원과 관리자를 위한 안전한 단일 회사 근태관리</p></div><div class="hero-visual"><div class="hero-blob"></div><div class="preview-card"><div class="preview-head"><span>오늘의 출근 현황</span><span class="live">● 실시간</span></div><div class="preview-stat"><div><strong>24</strong><small>전체 직원</small></div><div><strong>18</strong><small>출근 완료</small></div><div><strong>96<span style="font-size:12px">%</span></strong><small>출근율</small></div></div><div class="preview-row"><span class="avatar">김</span><span><b>김민준</b><small>생산 1팀 · FP-1024</small></span><span class="pill pill-green">정상 출근</span></div><div class="preview-row"><span class="avatar">이</span><span><b>이서연</b><small>품질관리팀 · FP-1031</small></span><span class="pill pill-amber">지각</span></div><div class="preview-row"><span class="avatar">박</span><span><b>박도윤</b><small>생산 2팀 · FP-1048</small></span><span class="pill pill-blue">근무 중</span></div></div><div class="floating-qr"><span class="qr-mini">▦</span><span><b>오늘의 개인 QR</b><small>안전하게 매일 새로 발급</small></span></div></div></section><section class="section" id="features"><div class="section-inner"><div class="section-heading"><div class="eyebrow">MADE FOR YOUR WORKPLACE</div><h2>근태관리, 더 간편하고 정확하게</h2><p>현장에 필요한 기능만 직관적으로. 직원과 관리자의 하루를 더 가볍게 만듭니다.</p></div><div class="feature-grid">${[['▦','QR코드 기반 간편한 출퇴근','개인 QR을 스캔해 출퇴근을 빠르고 정확하게 기록합니다.'],['◉','실시간 근태 현황 관리','오늘 출근 현황과 승인 대기 직원을 한눈에 확인합니다.'],['▤','직원별 출퇴근 기록','구성원별 기록을 날짜와 부서 기준으로 간편하게 조회합니다.'],['◷','자동 지각 및 조퇴 판정','등록된 근무 일정에 따라 근태 상태를 자동으로 계산합니다.'],['⌁','근태 통계 및 보고서','기간별·부서별 출근율을 확인하고 CSV로 내려받습니다.'],['▣','PC·모바일 통합 지원','PC, 태블릿, 스마트폰 어디서나 자연스럽게 사용할 수 있습니다.']].map(x=>`<article class="feature-card"><span class="feature-icon">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></div></section><section class="section" id="steps" style="background:#f0f4fa"><div class="section-inner"><div class="section-heading"><div class="eyebrow">SIMPLE WORKFLOW</div><h2>시작부터 출퇴근까지, 다섯 단계</h2><p>관리자 승인 후 개인 QR을 발급받아 간단하게 인증하세요.</p></div><div class="steps">${['근로자 회원가입','관리자 승인','개인 QR 발급','관리자 QR 스캔','출퇴근 기록 완료'].map((x,i)=>`<div class="step"><span class="step-num">${i+1}</span><strong>${x}</strong></div>`).join('')}</div></div></section><section class="section"><div class="section-inner"><div class="cta-band"><div><div class="eyebrow" style="color:#9bbcff">FACTORYPASS</div><h2 style="margin:10px 0">우리 현장의 근태관리,<br>오늘부터 간편하게</h2><p>근로자 계정으로 가입하고 관리자 승인을 기다려 주세요.</p></div><a class="btn btn-primary" href="/signup">근로자 회원가입 <span>→</span></a></div></div></section></main><footer class="footer"><div class="footer-inner"><div>${logo()}<p>Copyright © ${new Date().getFullYear()} FactoryPass. All rights reserved.</p></div><div class="footer-links"><a href="#features">서비스 소개</a><a href="#" data-static="개인정보처리방침은 회사 환경설정에 따라 고지됩니다.">개인정보처리방침</a><a href="#" data-static="이용약관은 회사 환경설정에 따라 고지됩니다.">이용약관</a><a href="mailto:">문의 안내</a></div></div></footer>`;$('#menu-toggle').onclick=()=>$('#nav-links').classList.toggle('open')}
function authPage(signup=false){app.innerHTML=`<div class="auth-shell"><aside class="auth-side">${logo()}<div class="auth-side-copy"><div class="eyebrow" style="color:#aac5ff">${signup?'JOIN YOUR TEAM':'ATTENDANCE, SIMPLIFIED'}</div><h1>${signup?'현장의 하루를 더 편리하게.':'QR코드 하나로 시작하는\n스마트한 출퇴근.'}</h1><p>FactoryPass는 우리 회사 구성원과 관리자를 위한 근태관리 서비스입니다. 안전하게 로그인하고 오늘의 근태 현황을 확인하세요.</p></div><div class="auth-foot">© ${new Date().getFullYear()} FactoryPass · 단일 회사 근태관리</div></aside><main class="auth-main"><section class="auth-box"><a class="link" href="/">← 메인으로</a><h2>${signup?'근로자 회원가입':'다시 만나 반가워요'}</h2><p class="auth-sub">${signup?'가입 후 관리자의 승인을 기다려 주세요.':'계정으로 로그인해 FactoryPass를 이용하세요.'}</p><div class="auth-error" id="auth-error"></div><form id="auth-form">${signup?`<div class="field"><label for="name">이름</label><input id="name" name="name" autocomplete="name" required maxlength="80" placeholder="홍길동"></div><div class="form-row"><div class="field"><label for="employeeNo">사번</label><input id="employeeNo" name="employeeNo" required maxlength="40" placeholder="예: FP-1024"></div><div class="field"><label for="department">부서</label><input id="department" name="department" required maxlength="80" placeholder="예: 생산 1팀"></div></div>`:''}<div class="field"><label for="identity">${signup?'이메일 또는 로그인 아이디':'아이디 또는 이메일'}</label><input id="identity" name="identity" autocomplete="username" required maxlength="120" placeholder="${signup?'이메일 또는 사용할 아이디':'아이디 또는 이메일'}"></div><div class="field"><label for="password">비밀번호</label><div style="display:flex;gap:6px"><input id="password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required minlength="${signup?'10':'1'}" maxlength="128" placeholder="${signup?'10자 이상 입력해 주세요':'비밀번호를 입력하세요'}"><button type="button" class="small-btn" id="password-toggle">표시</button></div></div>${signup?`<div class="field"><label for="confirm">비밀번호 확인</label><input id="confirm" name="confirm" type="password" autocomplete="new-password" required minlength="10" maxlength="128"></div><label class="check-row"><input type="checkbox" name="consent" required><span>개인정보 수집 및 이용에 동의합니다. 가입 정보는 회사의 근태관리 및 계정 운영 목적으로 사용됩니다.</span></label>`:`<label class="check-row"><input type="checkbox" name="remember" checked><span>로그인 상태 유지 (최대 7일)</span></label>`}<button class="btn btn-primary auth-submit" type="submit">${signup?'가입 신청':'로그인'}</button></form><p class="auth-switch">${signup?'이미 계정이 있으신가요?':'아직 계정이 없으신가요?'} <a href="${signup?'/login':'/signup'}">${signup?'로그인':'근로자 회원가입'}</a></p><p class="auth-note">관리자 계정은 일반 회원가입으로 만들 수 없습니다. 최초 관리자 설정은 서버 명령으로 안전하게 진행합니다.</p></section></main></div>`;$('#password-toggle').onclick=()=>{const p=$('#password');p.type=p.type==='password'?'text':'password';$('#password-toggle').textContent=p.type==='password'?'표시':'숨기기'};$('#auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),err=$('#auth-error');err.style.display='none';const body=signup?{name:f.get('name'),employeeNo:f.get('employeeNo'),department:f.get('department'),identity:f.get('identity'),password:f.get('password'),confirm:f.get('confirm'),consent:f.get('consent')==='on'}:{identity:f.get('identity'),password:f.get('password'),remember:f.get('remember')==='on'};if(signup&&body.password!==body.confirm){err.textContent='비밀번호가 일치하지 않습니다.';err.style.display='block';return}const submit=$('.auth-submit');submit.disabled=true;try{const result=await api(signup?'/auth/signup':'/auth/login',{method:'POST',body:JSON.stringify(body)});if(signup){location.href='/signup-complete'}else {window.__csrf=result.csrf;sessionStorage.removeItem('fp_pending_verify');location.href=result.redirect||'/';}}catch(x){err.textContent=x.message;err.style.display='block';}finally{submit.disabled=false}}}
const adminLinks=[['/admin','▦','대시보드'],['/admin/employees','♙','직원 관리'],['/admin/attendance','▤','근태 출석부'],['/admin/schedules','◷','근무 일정'],['/admin/statistics','⌁','근태 통계'],['/kiosk','▣','Kiosk 출퇴근 인증','new-tab'],['/admin/devices','▤','QR 단말기 관리'],['/admin/settings','⚙','환경설정']],employeeLinks=[['/employee','▦','내 대시보드'],['/employee/attendance','▤','내 근태 기록'],['/employee/profile','♙','내 정보']];
function shell(path,title){const admin=path.startsWith('/admin'),links=admin?adminLinks:employeeLinks;app.innerHTML=`<div class="app-layout"><aside class="sidebar" id="sidebar">${logo()}<div class="workspace"><span class="avatar">${esc((user?.name||'F')[0])}</span><div><strong>${esc(user?.name||'사용자')}</strong><small>${admin?'관리자':'근로자'} · ${esc(user?.department||'FactoryPass')}</small></div></div><div class="side-label">${admin?'WORKSPACE':'MY ATTENDANCE'}</div><nav class="side-nav">${links.map(l=>`<a class="side-link ${l[0]===path?'active':''}" href="${l[0]}" ${l[3]==='new-tab'?'target="_blank" rel="noopener noreferrer"':''}><span class="side-symbol">${l[1]}</span>${l[2]}</a>`).join('')}</nav><div class="side-bottom">안전한 회사 전용 근태관리</div></aside><main class="main-area"><header class="topbar"><button class="mobile-menu" id="side-toggle" aria-label="메뉴">☰</button><div class="top-title">${title}</div><div class="top-meta"><span class="top-date">${dt()}</span><span class="user-chip"><span class="avatar">${esc((user?.name||'F')[0])}</span><span>${esc(user?.name||'')}</span></span><button class="small-btn" id="logout">로그아웃</button></div></header><div class="content" id="view"></div>${!admin?`<nav class="employee-mobile-nav">${links.map(l=>`<a class="${l[0]===path?'active':''}" href="${l[0]}"><b>${l[1]}</b>${l[2].replace('내 ','')}</a>`).join('')}</nav>`:''}</main></div>`;$('#side-toggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#logout').onclick=async()=>{try{await api('/auth/logout',{method:'POST',body:'{}'})}catch{}location.href='/'};return $('#view')}
const empty=(msg='표시할 데이터가 없습니다.')=>`<div class="empty"><div class="empty-icon">◎</div>${msg}</div>`,badge=(s)=>`<span class="pill ${s==='정상 출근'||s==='퇴근 완료'||s==='승인됨'?'pill-green':s==='지각'||s==='승인 대기'?'pill-amber':s==='미출근'||s==='결근'?'pill-red':'pill-blue'}">${esc(s||'—')}</span>`,shortDate=s=>s?new Date(`${s}T00:00:00+09:00`).toLocaleDateString('ko-KR',{month:'numeric',day:'numeric'}):'—';
async function loadAdminHome(v){try{const d=await api('/admin/dashboard');v.innerHTML=`<div class="page-head"><div><h1>안녕하세요, ${esc(user.name)}님</h1><p>오늘의 근태 현황을 확인하세요. <b>${dt()}</b></p></div></div><div class="stats-grid">${[['전체 직원',d.stats.total,'등록된 근로자'],['오늘 출근',d.stats.present,'출근 기록 기준'],['정상 출근',d.stats.normal,'정시 출근'],['지각',d.stats.late,'일정 기준 판정'],['미출근',d.stats.absent,'오늘 출근 기록 없음'],['퇴근 완료',d.stats.checkedOut,'퇴근 기록 기준']].map((x,i)=>`<article class="stat-card"><div class="stat-label"><i class="stat-accent" style="background:${['#2766dc','#15966d','#15966d','#d99a2b','#d24d57','#5580d9'][i]}"></i>${x[0]}</div><div class="stat-value">${x[1]??0}</div><div class="stat-note">${x[2]}</div></article>`).join('')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>최근 출퇴근 기록</h2><p>QR 인증으로 저장된 최신 기록</p></div><a class="link" href="/admin/attendance">전체 보기 →</a></div>${d.recent?.length?`<div class="table-wrap"><table><thead><tr><th>직원</th><th>부서</th><th>유형</th><th>인증 시간</th><th>상태</th></tr></thead><tbody>${d.recent.map(r=>`<tr><td>${esc(r.name)} <small class="muted">${esc(r.employee_no)}</small></td><td>${esc(r.department||'—')}</td><td>${r.check_out?'퇴근':'출근'}</td><td>${timeFmt(r.check_out||r.check_in)}</td><td>${badge(r.status||'근무 중')}</td></tr>`).join('')}</tbody></table></div>`:empty('아직 출퇴근 기록이 없습니다.')}</section><div class="stack"><section class="panel"><div class="panel-head"><div><h2>최근 7일 출근율</h2><p>근무일정 기준 출근율</p></div></div><div class="chart-area"><canvas id="home-chart"></canvas></div></section></div></div>`;drawChart($('#home-chart'),d.trend?.labels||[],d.trend?.values||[])}catch(e){v.innerHTML=`<div class="notice">데이터를 불러오지 못했습니다: ${esc(e.message)}. D1 데이터베이스 바인딩과 관리자 초기 설정을 확인해 주세요.</div>`}}
function drawChart(canvas,labels,values,type='line'){if(!canvas||!window.Chart)return;chartInstances.forEach(c=>c.destroy());chartInstances=[];chartInstances.push(new Chart(canvas,{type,data:{labels,datasets:[{label:'출근율(%)',data:values,borderColor:'#2766dc',backgroundColor:'rgba(39,102,220,.12)',fill:true,tension:.35,pointRadius:3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,max:100,ticks:{callback:v=>v+'%'}},x:{grid:{display:false}}}}}))}
async function employees(v){v.innerHTML=`<div class="page-head"><div><h1>직원 관리</h1><p>직원 계정과 이용 상태를 관리합니다.</p></div></div><div class="panel table-panel"><div class="toolbar"><div class="toolbar-group"><input id="employee-search" type="search" placeholder="이름 또는 사번 검색"><select id="employee-status"><option value="">모든 계정 상태</option><option value="pending">기존 승인 대기</option><option value="approved">활성</option><option value="disabled">비활성</option><option value="rejected">거절됨</option></select><select id="employee-dept"><option value="">모든 부서</option></select></div><span class="muted" id="employee-count"></span></div><div id="employee-table"></div></div>`;let rows=[];try{({employees:rows}=await api('/admin/employees'))}catch(e){$('#employee-table').innerHTML=empty(esc(e.message));return}const depts=[...new Set(rows.map(x=>x.department).filter(Boolean))];$('#employee-dept').innerHTML='<option value="">모든 부서</option>'+depts.map(x=>`<option>${esc(x)}</option>`).join('');const render=()=>{const q=$('#employee-search').value.toLowerCase(),s=$('#employee-status').value,d=$('#employee-dept').value,filtered=rows.filter(x=>(!q||`${x.name} ${x.employee_no} ${x.email}`.toLowerCase().includes(q))&&(!s||x.status===s)&&(!d||x.department===d));$('#employee-count').textContent=`${filtered.length}명`;$('#employee-table').innerHTML=filtered.length?`<div class="table-wrap"><table><thead><tr><th>이름</th><th>사번</th><th>부서</th><th>이메일 / 아이디</th><th>가입일</th><th>상태</th><th>관리</th></tr></thead><tbody>${filtered.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.employee_no)}</td><td>${esc(x.department||'—')}</td><td>${esc(x.email||x.username)}</td><td>${shortDate(x.created_at?.slice(0,10))}</td><td>${badge(({pending:'기존 승인 대기',approved:'활성',disabled:'비활성',rejected:'사용 제한'})[x.status]||x.status)}</td><td><div class="table-actions">${x.status==='disabled'?`<button class="small-btn" data-enable="${x.id}">재활성화</button>`:x.status==='approved'?`<button class="small-btn" data-disable="${x.id}">비활성화</button>`:''}<button class="small-btn" data-records="${x.id}">근태</button></div></td></tr>`).join('')}</tbody></table></div>`:empty()};$('#employee-search').oninput=render;$('#employee-status').onchange=render;$('#employee-dept').onchange=render;render();$('#employee-table').onclick=async e=>{const b=e.target.closest('button[data-disable],button[data-enable],button[data-records]');if(!b)return;if(b.dataset.records){location.href='/admin/attendance?employee='+encodeURIComponent(b.dataset.records);return}const action=b.dataset.disable?'disable':'enable';try{await api(`/admin/employees/${b.dataset.disable||b.dataset.enable}/${action}`,{method:'POST',body:'{}'});toast('계정 상태를 변경했습니다.');employees(v)}catch(x){toast(x.message)}}}
async function attendance(v,employeeFilter=''){v.innerHTML=`<div class="page-head"><div><h1>근태 출석부</h1><p>QR 인증 기록과 근무 상태를 조회합니다.</p></div><button class="btn" id="csv">↓ CSV 다운로드</button></div><div class="panel table-panel"><div class="toolbar"><div class="toolbar-group"><input type="date" id="att-from"><input type="date" id="att-to"><input type="search" id="att-search" placeholder="이름 또는 사번"><select id="att-status"><option value="">모든 근태 상태</option>${['정상 출근','지각','근무 중','퇴근 완료','미출근','결근'].map(x=>`<option>${x}</option>`).join('')}</select></div><button class="btn btn-soft" id="att-load">조회</button></div><div id="attendance-table"></div></div>`;$('#att-from').value=today();$('#att-to').value=today();async function load(){const p=new URLSearchParams({from:$('#att-from').value,to:$('#att-to').value,search:$('#att-search').value,status:$('#att-status').value});if(employeeFilter)p.set('employee',employeeFilter);try{const d=await api('/admin/attendance?'+p);$('#attendance-table').innerHTML=d.records.length?`<div class="table-wrap"><table><thead><tr><th>날짜</th><th>사번</th><th>직원 이름</th><th>부서</th><th>출근</th><th>퇴근</th><th>근무시간</th><th>상태</th><th>관리</th></tr></thead><tbody>${d.records.map(r=>`<tr><td>${esc(r.work_date)}</td><td>${esc(r.employee_no)}</td><td><b>${esc(r.name)}</b></td><td>${esc(r.department||'—')}</td><td>${r.check_in?timeFmt(r.check_in):'—'}</td><td>${r.check_out?timeFmt(r.check_out):'—'}</td><td>${r.work_minutes==null?'—':Math.floor(r.work_minutes/60)+'시간 '+r.work_minutes%60+'분'}</td><td>${(r.statuses||[r.status]).map(badge).join(' ')}</td><td><button class="small-btn" data-edit-record="${r.id}" data-in="${r.check_in||''}" data-out="${r.check_out||''}">수정</button></td></tr>`).join('')}</tbody></table></div>`:empty('선택한 조건의 기록이 없습니다.')}catch(e){$('#attendance-table').innerHTML=empty(esc(e.message))}}$('#att-load').onclick=load;load();$('#csv').onclick=async()=>{try{const p=new URLSearchParams({from:$('#att-from').value,to:$('#att-to').value});const r=await fetch('/api/admin/attendance.csv?'+p,{credentials:'same-origin'});if(!r.ok)throw new Error((await r.json()).error);const a=document.createElement('a');a.href=URL.createObjectURL(await r.blob());a.download=`factorypass-attendance-${today()}.csv`;a.click();URL.revokeObjectURL(a.href)}catch(e){toast(e.message)}};$('#attendance-table').onclick=async e=>{const b=e.target.closest('[data-edit-record]');if(!b)return;const checkIn=prompt('출근 시각 (ISO 형식, 비우면 변경 없음)',b.dataset.in);if(checkIn===null)return;const checkOut=prompt('퇴근 시각 (ISO 형식, 비우면 변경 없음)',b.dataset.out);if(checkOut===null)return;const reason=prompt('수정 사유를 입력하세요');if(!reason)return;try{await api(`/admin/attendance/${b.dataset.editRecord}`,{method:'PATCH',body:JSON.stringify({checkIn:checkIn||null,checkOut:checkOut||null,reason})});toast('기록과 수정 이력을 저장했습니다.');load()}catch(x){toast(x.message)}}}
async function legacyCameraScanner(v){v.innerHTML=`<div class="page-head"><div><h1>QR 스캐너</h1><p>승인된 직원의 오늘 QR을 스캔해 출퇴근을 기록합니다.</p></div><div class="mode-toggle"><button class="active" data-mode="in">출근</button><button data-mode="out">퇴근</button></div></div><div class="scanner-layout"><section class="panel"><div class="panel-head"><div><h2>카메라 스캔</h2><p>HTTPS 연결 및 카메라 권한이 필요합니다.</p></div></div><div class="scanner-frame" id="reader"><div class="scanner-placeholder">카메라 시작을 눌러 스캐너를 실행하세요.</div></div><div class="toolbar" style="padding:14px 0;border:0"><button class="btn btn-primary" id="start-camera">카메라 시작</button><button class="btn" id="stop-camera" disabled>카메라 종료</button><select id="camera-select" aria-label="카메라 선택"><option>카메라 선택</option></select></div><div class="notice">관리자가 출근/퇴근 모드를 선택한 후 QR을 스캔합니다. 동일 QR을 연속 인식해도 중복 기록은 서버에서 차단됩니다.</div></section><section class="panel"><div class="panel-head"><div><h2>인증 결과</h2><p>가장 최근 스캔 정보</p></div></div><div id="scan-result" class="empty">아직 스캔 결과가 없습니다.</div></section></div>`;let mode='in',scannerObj=null,busy=false,seen=new Map();$$('[data-mode]',v).forEach(b=>b.onclick=()=>{$$('[data-mode]',v).forEach(x=>x.classList.toggle('active',x===b));mode=b.dataset.mode});const result=$('#scan-result');async function onScan(text){if(busy||seen.has(text))return;busy=true;seen.set(text,Date.now());setTimeout(()=>seen.delete(text),4000);try{const d=await api('/admin/scan',{method:'POST',body:JSON.stringify({token:text,mode})});result.className='scanner-result';result.innerHTML=`<div class="profile-intro"><span class="avatar">${esc(d.employee.name[0])}</span><div><h2>${esc(d.employee.name)}</h2><p>${esc(d.employee.employee_no)} · ${esc(d.employee.department||'')}</p></div>${badge(d.status)}</div><div class="today-status"><div class="time-tile"><small>인증 구분</small><strong>${mode==='in'?'출근':'퇴근'}</strong></div><div class="time-tile"><small>인증 시간 (한국 표준시)</small><strong>${timeFmt(d.recordedAt)}</strong></div></div><p class="notice" style="margin-top:14px">${esc(d.message||'인증 성공 · 기록을 저장했습니다.')}</p>`;toast('출퇴근 기록이 저장되었습니다.')}catch(e){result.className='notice';result.innerHTML=`<b>인증 실패</b><br>${esc(e.message)}`}finally{setTimeout(()=>busy=false,1300)}}$('#start-camera').onclick=async()=>{try{if(!window.Html5Qrcode)throw new Error('QR 스캐너 라이브러리를 불러오지 못했습니다. 네트워크 연결을 확인하세요.');scannerObj=new Html5Qrcode('reader');const cameras=await Html5Qrcode.getCameras();if(!cameras.length)throw new Error('사용 가능한 카메라를 찾지 못했습니다.');$('#camera-select').innerHTML=cameras.map((c,i)=>`<option value="${esc(c.id)}">${esc(c.label||`카메라 ${i+1}`)}</option>`).join('');await scannerObj.start(cameras[0].id,{fps:10,qrbox:{width:230,height:230}},onScan,()=>{});$('#start-camera').disabled=true;$('#stop-camera').disabled=false}catch(e){toast(e.message);$('#reader').innerHTML=`<div class="scanner-placeholder">${esc(e.message)}<br>브라우저 카메라 권한을 허용하고 HTTPS 환경에서 다시 시도하세요.</div>`}};$('#stop-camera').onclick=async()=>{try{await scannerObj?.stop();scannerObj?.clear()}catch{}scannerObj=null;$('#start-camera').disabled=false;$('#stop-camera').disabled=true;$('#reader').innerHTML='<div class="scanner-placeholder">카메라가 종료되었습니다.</div>'};$('#camera-select').onchange=async e=>{if(!scannerObj)return;try{await scannerObj.stop();await scannerObj.start(e.target.value,{fps:10,qrbox:{width:230,height:230}},onScan,()=>{})}catch(x){toast(x.message)}}}
function scanner(v){v.innerHTML=`<div class="page-head"><div><h1>기존 QR 스캐너</h1><p>카메라 스캐너 화면은 Kiosk 방식으로 전환될 예정입니다.</p></div></div><section class="panel"><div class="notice"><b>안내</b><br>/admin/scanner의 기존 카메라 스캐너는 관리자 메뉴에서 제거되었습니다. Kiosk 출퇴근 인증으로 전환될 예정이며 이번 단계에서는 출퇴근 인증을 수행하지 않습니다.</div><p><a class="btn btn-soft" href="/kiosk" target="_blank" rel="noopener noreferrer">Kiosk 안내 열기</a></p></section>`}
function kioskPage(){app.innerHTML=`<main class="auth-main" style="min-height:100vh"><section class="auth-box"><div class="brand">${logo()}</div><div class="eyebrow">FACTORYPASS KIOSK</div><h1 style="font-size:29px">FactoryPass Kiosk 출퇴근 인증</h1><p class="auth-sub">USB QR 스캐너 연동 및 출퇴근 인증 기능은 다음 개발 단계에서 추가됩니다.</p><div class="notice" role="status"><b>현재 사용 불가</b><br>이 Kiosk 화면은 준비 중입니다. 현재는 QR 스캔 또는 출퇴근 기록을 처리하지 않습니다.</div><p class="muted" style="margin-top:18px">출퇴근 인증 기능이 활성화되기 전까지 이 페이지에서 기록이 생성되지 않습니다.</p><a class="btn" href="/">FactoryPass 홈으로</a></section></main>`}
async function devicesPage(v){v.innerHTML=`<div class="page-head"><div><h1>QR 단말기 관리</h1><p>단말기를 등록하고 활성 상태 및 실제 사용 기록을 관리합니다.</p></div><button class="btn btn-soft" id="devices-refresh">새로고침</button></div><section class="panel"><div class="panel-head"><div><h2>신규 단말기 등록</h2><p>식별자는 영문·숫자·하이픈·밑줄 3~64자로 입력하세요.</p></div></div><div id="device-message"></div><form id="device-form" class="form-row"><div class="field"><label for="device-code">단말기 식별자</label><input id="device-code" name="deviceCode" required maxlength="64" pattern="[A-Za-z0-9_-]{3,64}" placeholder="예: FP-K01"></div><div class="field"><label for="device-name">단말기 이름</label><input id="device-name" name="name" required maxlength="100" placeholder="단말기 이름"></div><div class="field"><label for="device-location">설치 위치</label><input id="device-location" name="location" required maxlength="200" placeholder="건물·층·출입구"></div><button class="btn btn-primary" type="submit">단말기 등록</button></form></section><section class="panel table-panel"><div class="panel-head"><div><h2>등록 단말기</h2><p>최근 사용은 실제 서버 기록을 기준으로 표시합니다. 사용 기록이 없으면 “기록 없음”으로 표시됩니다.</p></div><span class="muted" id="device-count"></span></div><div id="device-list"><div class="empty">불러오는 중…</div></div></section><section class="panel" id="device-usage-panel"><div class="panel-head"><div><h2 id="device-usage-title">단말기 사용 기록</h2><p>선택한 단말기의 실제 사용 이력 (최근 50건)</p></div></div><div id="device-usage-list" class="empty">단말기 행에서 사용 기록을 선택하세요.</div></section>`;const msg=$('#device-message');async function loadDevices(){try{const d=await api('/admin/devices');$('#device-count').textContent=`${d.devices.length}대`;$('#device-list').innerHTML=d.devices.length?`<div class="table-wrap"><table><thead><tr><th>식별자</th><th>단말기 이름</th><th>설치 위치</th><th>상태</th><th>최근 사용</th><th>사용 횟수</th><th>관리</th></tr></thead><tbody>${d.devices.map(x=>`<tr><td><code>${esc(x.device_code)}</code></td><td>${esc(x.name)}</td><td>${esc(x.location)}</td><td>${badge(x.status==='active'?'활성':'비활성')}</td><td>${x.last_used_at?`${shortDate(x.last_used_at.slice(0,10))} ${timeFmt(x.last_used_at)}`:'기록 없음'}</td><td>${x.usage_count}</td><td><div class="table-actions"><button class="small-btn" data-device-action="edit" data-id="${x.id}" data-name="${esc(x.name)}" data-location="${esc(x.location)}">정보 수정</button><button class="small-btn" data-device-action="${x.status==='active'?'deactivate':'activate'}" data-id="${x.id}">${x.status==='active'?'비활성화':'활성화'}</button><button class="small-btn" data-device-action="usage" data-id="${x.id}" data-name="${esc(x.name)}">사용 기록</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><div class="empty-icon">▤</div>등록된 단말기가 없습니다. 위 양식에서 단말기를 등록하세요.</div>'}catch(e){$('#device-list').innerHTML=empty(esc(e.message))}}$('#device-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/admin/devices',{method:'POST',body:JSON.stringify({deviceCode:f.get('deviceCode'),name:f.get('name'),location:f.get('location')})});msg.innerHTML='<div class="notice">단말기를 등록했습니다. 기본 상태는 비활성이며 사용할 단말기는 명시적으로 활성화하세요.</div>';e.currentTarget.reset();await loadDevices()}catch(x){msg.innerHTML=`<div class="notice">${esc(x.message)}</div>`}};$('#devices-refresh').onclick=loadDevices;$('#device-list').onclick=async e=>{const b=e.target.closest('[data-device-action]');if(!b)return;const action=b.dataset.deviceAction,id=b.dataset.id;try{if(action==='edit'){const name=prompt('단말기 이름',b.dataset.name);if(name===null)return;const location=prompt('설치 위치',b.dataset.location);if(location===null)return;await api(`/admin/devices/${id}`,{method:'PATCH',body:JSON.stringify({name,location})});msg.innerHTML='<div class="notice">단말기 정보를 수정했습니다.</div>';await loadDevices();return}if(action==='usage'){const data=await api(`/admin/devices/${id}/usage`);$('#device-usage-title').textContent=`${data.device.name} 사용 기록`;$('#device-usage-list').innerHTML=data.logs.length?`<div class="table-wrap"><table><thead><tr><th>사용 시각</th><th>활동</th><th>결과</th><th>사번</th><th>직원</th></tr></thead><tbody>${data.logs.map(log=>`<tr><td>${esc(log.used_at)}</td><td>${log.activity==='scan'?'QR 인증':'통신'}</td><td>${badge(log.outcome==='success'?'성공':'실패')}</td><td>${esc(log.employee_no||'—')}</td><td>${esc(log.name||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">이 단말기의 사용 기록이 없습니다.</div>';return}await api(`/admin/devices/${id}/${action}`,{method:'POST',body:'{}'});msg.innerHTML=`<div class="notice">단말기를 ${action==='activate'?'활성화':'비활성화'}했습니다.</div>`;await loadDevices()}catch(x){msg.innerHTML=`<div class="notice">${esc(x.message)}</div>`}};await loadDevices()}
async function schedules(v){v.innerHTML=`<div class="page-head"><div><h1>근무 일정</h1><p>기본 근무시간과 부서별 일정을 관리합니다. 야간 일정은 퇴근일이 다음 날로 자동 계산됩니다.</p></div></div><div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2>기본 근무시간</h2><p>회사 기본 일정 및 지각 판정 기준</p></div></div><form id="schedule-form"><div class="form-row"><div class="field"><label>출근 시간</label><input type="time" name="startTime" value="09:00" required></div><div class="field"><label>퇴근 시간</label><input type="time" name="endTime" value="18:00" required></div></div><div class="field"><label>지각 유예 (분)</label><input type="number" name="graceMinutes" value="5" min="0" max="180"></div><div class="field"><label>일정 유형</label><select name="scope"><option value="default">회사 기본</option><option value="department">부서별</option><option value="employee">직원별</option></select></div><div class="field hidden" id="scope-target"><label>부서명 또는 사번</label><input name="target" maxlength="80"></div><button class="btn btn-primary">일정 저장</button></form></section><section class="panel"><div class="panel-head"><div><h2>등록된 일정</h2><p>적용 우선순위: 직원별 → 부서별 → 기본</p></div></div><div id="schedule-list">불러오는 중…</div></section></div><section class="panel" style="margin-top:15px"><div class="panel-head"><div><h2>휴무일</h2><p>근무일정에서 제외할 날짜를 등록합니다.</p></div></div><div class="toolbar"><div class="toolbar-group"><input type="date" id="holiday-date"><input id="holiday-name" placeholder="휴무명"></div><button class="btn btn-soft" id="holiday-add">휴무일 등록</button></div><div id="holiday-list"></div></section>`;const form=$('#schedule-form');try{const d=await api('/admin/schedules');$('#schedule-list').innerHTML=d.schedules.length?`<div class="table-wrap"><table><thead><tr><th>적용 대상</th><th>출근</th><th>퇴근</th><th>유예</th></tr></thead><tbody>${d.schedules.map(x=>`<tr><td>${esc(x.scope==='default'?'회사 기본':x.target||x.scope)}</td><td>${esc(x.start_time)}</td><td>${esc(x.end_time)}</td><td>${x.grace_minutes}분</td></tr>`).join('')}</tbody></table></div>`:empty()}catch(e){$('#schedule-list').innerHTML=empty(esc(e.message))}const loadHolidays=async()=>{try{const d=await api('/admin/holidays');$('#holiday-list').innerHTML=d.holidays.length?d.holidays.map(h=>`<div class="mini-item" style="padding:11px 0;border-bottom:1px solid var(--line)"><div class="mini-info"><b>${esc(h.holiday_date)}</b><small>${esc(h.name||'휴무')}</small></div><button class="small-btn" data-holiday-del="${h.id}">삭제</button></div>`).join(''):empty()}catch(e){$('#holiday-list').innerHTML=empty(esc(e.message))}};loadHolidays();form.scope.onchange=()=>$('#scope-target').classList.toggle('hidden',form.scope.value==='default');form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);try{await api('/admin/schedules',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});toast('근무 일정을 저장했습니다.');schedules(v)}catch(x){toast(x.message)}};$('#holiday-add').onclick=async()=>{try{await api('/admin/holidays',{method:'POST',body:JSON.stringify({date:$('#holiday-date').value,name:$('#holiday-name').value})});toast('휴무일을 등록했습니다.');loadHolidays()}catch(e){toast(e.message)}};$('#holiday-list').onclick=async e=>{const b=e.target.closest('[data-holiday-del]');if(!b)return;try{await api('/admin/holidays/'+b.dataset.holidayDel,{method:'DELETE'});loadHolidays()}catch(x){toast(x.message)}}}
async function statistics(v){v.innerHTML=`<div class="page-head"><div><h1>근태 통계</h1><p>조회 기간별 출근율과 구성원별 근무 현황을 살펴봅니다.</p></div><button class="btn" id="stats-csv">↓ CSV 다운로드</button></div><div class="toolbar" style="background:#fff;border:1px solid var(--line);border-radius:10px;margin-bottom:15px"><div class="toolbar-group"><label class="muted">시작일</label><input type="date" id="stats-from"><label class="muted">종료일</label><input type="date" id="stats-to"></div><button class="btn btn-primary" id="stats-load">통계 조회</button></div><div class="stats-grid" id="stats-cards"></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>일별 출근율</h2><p>선택 기간의 일자별 추이</p></div></div><div class="chart-area"><canvas id="daily-chart"></canvas></div></section><section class="panel"><div class="panel-head"><div><h2>부서별 출근율</h2><p>선택 기간의 부서 비교</p></div></div><div class="chart-area"><canvas id="dept-chart"></canvas></div></section></div><section class="panel"><div class="panel-head"><div><h2>직원별 근태</h2><p>지각·결근 횟수 및 기록 근무시간</p></div></div><div id="stats-table"></div></section>`;const end=today(),start=new Date(Date.now()-29*864e5);$('#stats-from').value=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul'}).format(start);$('#stats-to').value=end;async function load(){const q=new URLSearchParams({from:$('#stats-from').value,to:$('#stats-to').value});try{const d=await api('/admin/statistics?'+q);$('#stats-cards').innerHTML=[['평균 출근율',`${d.overall.rate}%`],['총 근무일',d.overall.days],['지각 횟수',d.overall.late],['결근 횟수',d.overall.absent]].map(x=>`<article class="stat-card"><div class="stat-label">${x[0]}</div><div class="stat-value">${x[1]}</div></article>`).join('');drawChart($('#daily-chart'),d.daily.map(x=>shortDate(x.date)),d.daily.map(x=>x.rate));if(window.Chart){const old=chartInstances.splice(0);old.forEach(c=>c.destroy());chartInstances.push(new Chart($('#daily-chart'),{type:'line',data:{labels:d.daily.map(x=>shortDate(x.date)),datasets:[{data:d.daily.map(x=>x.rate),borderColor:'#2766dc',backgroundColor:'#2766dc20',fill:true,tension:.3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,max:100,ticks:{callback:x=>x+'%'}}}}}));chartInstances.push(new Chart($('#dept-chart'),{type:'bar',data:{labels:d.departments.map(x=>x.department),datasets:[{data:d.departments.map(x=>x.rate),backgroundColor:'#5a88e8',borderRadius:5}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,max:100,ticks:{callback:x=>x+'%'}}}}}))}$('#stats-table').innerHTML=d.employees.length?`<div class="table-wrap"><table><thead><tr><th>사번</th><th>직원</th><th>부서</th><th>지각</th><th>결근</th><th>근무시간</th></tr></thead><tbody>${d.employees.map(x=>`<tr><td>${esc(x.employee_no)}</td><td>${esc(x.name)}</td><td>${esc(x.department||'—')}</td><td>${x.late}</td><td>${x.absent}</td><td>${Math.floor(x.minutes/60)}시간 ${x.minutes%60}분</td></tr>`).join('')}</tbody></table></div>`:empty()}catch(e){toast(e.message)}}$('#stats-load').onclick=load;load();$('#stats-csv').onclick=()=>{location.href=`/api/admin/statistics.csv?from=${$('#stats-from').value}&to=${$('#stats-to').value}`}}
async function settings(v){v.innerHTML=`<div class="page-head"><div><h1>환경설정</h1><p>회사 정보, 부서, QR 정책 및 계정을 관리합니다.</p></div></div><div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2>회사 정보</h2><p>서비스에 표시할 회사 이름</p></div></div><form id="company-form"><div class="field"><label>회사명</label><input name="company_name" maxlength="100" required></div><button class="btn btn-primary">저장</button></form></section><section class="panel"><div class="panel-head"><div><h2>부서 관리</h2><p>근로자 회원가입 시 부서 입력에 사용됩니다.</p></div></div><div class="toolbar" style="padding:0 0 14px;border:0"><input id="new-dept" placeholder="새 부서 이름"><button class="btn btn-soft" id="add-dept">부서 등록</button></div><div id="dept-list"></div></section><section class="panel"><div class="panel-head"><div><h2>QR 인증 정책</h2><p>하루에 발급되는 직원별 QR 토큰 정책</p></div></div><div class="notice">QR 토큰은 승인된 근로자에게 근무일 단위로 발급되며 개인정보를 포함하지 않습니다. 오늘 날짜와 일치하지 않는 토큰은 서버에서 거부됩니다. HTTPS 접속과 안전한 세션 쿠키가 필요합니다.</div><p class="muted" style="font-size:11px">동적 QR 단기 회전 정책은 별도 설정으로 확장 가능하도록 토큰 테이블에 만료 시간을 보관합니다.</p></section><section class="panel"><div class="panel-head"><div><h2>관리자 계정 정보</h2><p>비밀번호는 서버에서 안전하게 해시됩니다.</p></div></div><form id="password-form"><div class="field"><label>현재 비밀번호</label><input name="currentPassword" type="password" autocomplete="current-password" required></div><div class="field"><label>새 비밀번호 (10자 이상)</label><input name="newPassword" type="password" autocomplete="new-password" minlength="10" required></div><button class="btn btn-primary">비밀번호 변경</button></form></section></div>`;try{const d=await api('/admin/settings');$('input[name=company_name]').value=d.settings.company_name||'';$('#dept-list').innerHTML=d.departments.length?d.departments.map(x=>`<div class="mini-item" style="padding:10px 0;border-bottom:1px solid var(--line)"><div class="mini-info"><b>${esc(x.name)}</b></div><button class="small-btn" data-dept-del="${x.id}">삭제</button></div>`).join(''):empty()}catch(e){toast(e.message)}$('#company-form').onsubmit=async e=>{e.preventDefault();try{await api('/admin/settings',{method:'PATCH',body:JSON.stringify({company_name:$('input[name=company_name]').value})});toast('회사 설정을 저장했습니다.')}catch(x){toast(x.message)}};$('#add-dept').onclick=async()=>{try{await api('/admin/departments',{method:'POST',body:JSON.stringify({name:$('#new-dept').value})});toast('부서를 등록했습니다.');settings(v)}catch(e){toast(e.message)}};$('#dept-list').onclick=async e=>{const b=e.target.closest('[data-dept-del]');if(!b)return;try{await api('/admin/departments/'+b.dataset.deptDel,{method:'DELETE'});settings(v)}catch(x){toast(x.message)}};$('#password-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/auth/password',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});toast('비밀번호를 변경했습니다.');e.currentTarget.reset()}catch(x){toast(x.message)}}}
let personalQrPollTimer=null;
async function renderPersonalQr(){if(personalQrPollTimer)clearInterval(personalQrPollTimer);const box=$('#qr-box'),status=$('#qr-status');status.textContent='개인 QR을 발급하는 중입니다…';try{const qr=await api('/employee/qr');box.replaceChildren();if(!window.QRCode)throw new Error('QR 표시 라이브러리를 불러오지 못했습니다.');new QRCode(box,{text:qr.verifyUrl,width:240,height:240,colorDark:'#172c4a',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});const expires=Date.parse(qr.expiresAt);async function update(){const left=Math.max(0,Math.ceil((expires-Date.now())/1000));if(!left){status.textContent='QR이 만료되었습니다. 새 QR을 발급해 주세요.';clearInterval(personalQrPollTimer);return}try{const data=await api('/employee/qr/status',{method:'POST',body:JSON.stringify({token:qr.token})});status.textContent=data.state==='active'?`스마트폰으로 촬영하세요 · ${left}초 후 만료`:data.state==='expired'?'QR이 만료되었습니다. 새로 발급해 주세요.':'QR이 교체되었습니다. 새 QR을 발급해 주세요.';if(data.state!=='active')clearInterval(personalQrPollTimer)}catch(error){status.textContent=`QR 상태 확인 실패: ${error.message}`}}await update();personalQrPollTimer=setInterval(update,3000)}catch(error){box.innerHTML=`<div class="qr-placeholder">${esc(error.message)}</div>`;status.textContent='QR 발급에 실패했습니다.'}}
async function employeeHome(v){v.innerHTML=`<div class="page-head"><div><h1>내 근태 대시보드</h1><p>${dt()} · 스마트폰으로 QR을 촬영해 본인 인증 화면을 여세요.</p></div></div><div class="employee-layout"><section class="panel qr-card"><div class="profile-intro" style="justify-content:center;text-align:left"><span class="avatar">${esc(user.name[0])}</span><div><h2>${esc(user.name)}</h2><p>${esc(user.employee_no)} · ${esc(user.department||'부서')}</p></div></div><div class="qr-date">개인 출퇴근 인증 QR · 60초 유효</div><div class="qr-box" id="qr-box"><div class="qr-placeholder">QR을 발급해 주세요.</div></div><div class="qr-status" id="qr-status">QR 발급 전</div><button class="btn btn-soft" id="qr-refresh" type="button">QR 발급 / 재발급</button><p class="qr-footnote">QR에는 개인정보가 아닌 일회용 무작위 토큰이 포함됩니다. 만료되면 재발급하세요. 이번 단계에서는 출퇴근 기록을 저장하지 않습니다.</p></section><div class="stack"><section class="panel"><div class="panel-head"><div><h2>오늘의 근태</h2><p>이번 단계의 QR은 본인 계정 인증 화면 진입까지만 지원합니다.</p></div></div><div id="today-record" class="today-status"></div></section><section class="panel"><div class="panel-head"><div><h2>최근 근태 기록</h2><a class="link" href="/employee/attendance">전체 보기 →</a></div></div><div id="recent-records"></div></section></div></div>`;try{const d=await api('/employee/dashboard');$('#today-record').innerHTML=`<div class="time-tile"><small>출근 시간</small><strong>${timeFmt(d.today?.check_in)}</strong></div><div class="time-tile"><small>퇴근 시간</small><strong>${timeFmt(d.today?.check_out)}</strong></div><div class="time-tile"><small>오늘 상태</small><strong style="font-size:14px">${badge(d.today?.status||'미출근')}</strong></div><div class="time-tile"><small>이번 달 지각</small><strong>${d.monthLate}회</strong></div>`;$('#recent-records').innerHTML=d.recent.length?`<div class="table-wrap"><table><thead><tr><th>날짜</th><th>출근</th><th>퇴근</th><th>상태</th></tr></thead><tbody>${d.recent.slice(0,6).map(r=>`<tr><td>${esc(r.work_date)}</td><td>${timeFmt(r.check_in)}</td><td>${timeFmt(r.check_out)}</td><td>${badge(r.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('아직 근태 기록이 없습니다.');$('#qr-refresh').onclick=renderPersonalQr;await renderPersonalQr()}catch(e){$('#qr-box').innerHTML=`<div class="qr-placeholder">${esc(e.message)}</div>`}}
async function employeeVerifyPage(token){app.innerHTML=`<main class="auth-main verify-shell"><section class="auth-box verify-card">${logo()}<div class="eyebrow">PERSONAL QR VERIFICATION</div><h1>QR 출퇴근 인증</h1><div id="verify-state" class="notice" role="status" aria-live="polite">QR과 로그인 계정을 확인하고 있습니다.</div><div id="verify-content"></div></section></main>`;const state=$('#verify-state'),content=$('#verify-content');if(!/^[a-f\d]{64}$/i.test(token||'')){state.textContent='QR 인증 주소가 올바르지 않습니다. 근로자 PC에서 QR을 다시 발급해 주세요.';return}try{const data=await api('/employee/qr/verify',{method:'POST',body:JSON.stringify({token})});state.textContent='본인 계정 일치 · QR 유효';content.innerHTML=`<div class="verify-employee"><span class="avatar">${esc(data.employee.name[0])}</span><div><strong>${esc(data.employee.name)}</strong><small>${esc(data.employee.employeeNo)} · ${esc(data.employee.department||'부서')}</small></div></div><div class="time-tile"><small>출퇴근 확인 화면</small><strong>${data.previewType==='in'?'출근 예정':'퇴근 예정'}</strong></div><p class="muted">QR 발급 근무일: ${esc(data.workDate)} · 만료 시각: ${timeFmt(data.expiresAt)}</p><button class="btn btn-primary" id="verify-confirm" type="button">출퇴근 확인 화면 열기</button><div class="notice hidden" id="verify-result" style="margin-top:14px" role="status" aria-live="polite"></div><p class="auth-note">이번 단계에서는 QR 소유자와 로그인 계정만 확인합니다. 실제 출퇴근 기록은 저장하지 않습니다.</p>`;const confirm=$('#verify-confirm');confirm.addEventListener('click',()=>{const result=$('#verify-result');result.classList.remove('hidden');result.textContent=`${data.employee.name}님의 ${data.previewType==='in'?'출근':'퇴근'} 확인 화면입니다. QR 인증이 완료되었습니다. 실제 출퇴근 기록은 저장되지 않았습니다.`;confirm.textContent='출퇴근 확인 완료';confirm.disabled=true;state.textContent='출퇴근 확인 화면이 열렸습니다.'})}catch(error){state.textContent=error.status===410?'QR이 만료되었습니다. 근로자 PC에서 QR을 다시 발급해 주세요.':error.status===404?'QR을 확인할 수 없습니다. 재발급되었거나 이미 사용된 QR일 수 있습니다. 근로자 PC에서 새 QR을 발급해 주세요.':error.status===403?'로그인 계정이 QR 발급자와 다르거나 사용할 수 없는 계정입니다. QR 발급 근로자 계정으로 로그인해 주세요.':error.message;content.innerHTML=`<a class="btn" href="/employee">근로자 대시보드로 돌아가기</a>`}}

async function employeeAttendance(v){v.innerHTML=`<div class="page-head"><div><h1>내 근태 기록</h1><p>본인의 출퇴근 내역과 월별 현황입니다.</p></div></div><div class="stats-grid" id="my-stats"></div><section class="panel table-panel"><div class="toolbar"><div class="toolbar-group"><input type="date" id="my-from"><input type="date" id="my-to"></div><button class="btn btn-soft" id="my-load">조회</button></div><div id="my-table"></div></section>`;$('#my-to').value=today();const d=new Date();d.setDate(1);$('#my-from').value=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul'}).format(d);async function load(){try{const x=await api(`/employee/attendance?from=${$('#my-from').value}&to=${$('#my-to').value}`);$('#my-stats').innerHTML=[['출근 일수',x.summary.present],['지각 횟수',x.summary.late],['결근 횟수',x.summary.absent],['근무 시간',`${Math.floor(x.summary.minutes/60)}시간`]].map(a=>`<article class="stat-card"><div class="stat-label">${a[0]}</div><div class="stat-value">${a[1]}</div></article>`).join('');$('#my-table').innerHTML=x.records.length?`<div class="table-wrap"><table><thead><tr><th>날짜</th><th>출근</th><th>퇴근</th><th>근무시간</th><th>상태</th></tr></thead><tbody>${x.records.map(r=>`<tr><td>${esc(r.work_date)}</td><td>${timeFmt(r.check_in)}</td><td>${timeFmt(r.check_out)}</td><td>${r.work_minutes==null?'—':`${Math.floor(r.work_minutes/60)}시간 ${r.work_minutes%60}분`}</td><td>${badge(r.status)}</td></tr>`).join('')}</tbody></table></div>`:empty()}catch(e){$('#my-table').innerHTML=empty(esc(e.message))}}$('#my-load').onclick=load;load()}
async function profile(v){v.innerHTML=`<div class="page-head"><div><h1>내 정보</h1><p>이름, 사번, 부서는 회사 관리자만 변경할 수 있습니다. 수정이 필요하면 관리자에게 요청하세요.</p></div></div><div class="settings-grid"><section class="panel"><div class="panel-head"><h2>계정 정보</h2></div><div class="field"><label>이름</label><input disabled value="${esc(user.name)}"></div><div class="field"><label>사번</label><input disabled value="${esc(user.employee_no)}"></div><div class="field"><label>부서</label><input disabled value="${esc(user.department||'—')}"></div><div class="field"><label>로그인 아이디 / 이메일</label><input disabled value="${esc(user.email||user.username)}"></div></section><section class="panel"><div class="panel-head"><h2>비밀번호 변경</h2></div><form id="profile-password"><div class="field"><label>현재 비밀번호</label><input name="currentPassword" type="password" required></div><div class="field"><label>새 비밀번호 (10자 이상)</label><input name="newPassword" type="password" minlength="10" required></div><button class="btn btn-primary">비밀번호 변경</button></form></section></div>`;$('#profile-password').onsubmit=async e=>{e.preventDefault();try{await api('/auth/password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});toast('비밀번호가 변경되었습니다.')}catch(x){toast(x.message)}}}
function signupComplete(){app.innerHTML=`<div class="auth-main" style="min-height:100vh"><div class="pending-box"><div class="pending-icon" style="background:#e6f5ee;color:#13805e">✓</div>${logo()}<h1>회원가입이 완료되었습니다.</h1><p>회원가입이 완료되었습니다. 로그인해 주세요.</p><a class="btn btn-primary" href="/login">로그인</a></div></div>`}
function staticError(msg){app.innerHTML=`<div class="auth-main" style="min-height:100vh"><section class="auth-box"><div class="brand-mark">F</div><h2>FactoryPass에 연결할 수 없습니다</h2><p class="auth-sub">${esc(msg)}</p><p class="auth-note">이 서비스는 Cloudflare Pages Functions와 D1 데이터베이스를 구성해야 실제로 작동합니다. README의 배포 설정을 확인하세요.</p><a class="btn btn-primary" href="/">메인으로</a></section></div>`}
﻿async function boot(){
 clearTimeout(window.__factoryPassBootTimer);
 const path=location.pathname.replace(/\/$/,'')||'/';
 if(path==='/privacy'||path==='/terms'){landing();return}
 if(path==='/kiosk'){kioskPage();return}
 if(path==='/signup-complete'){signupComplete();return}
 if(path==='/'){
  try{const d=await api('/auth/me');user=d.user;window.__csrf=d.csrf;location.replace(d.redirect);return}catch{landing();return}
 }
 if(path==='/login'||path==='/signup'){
  try{const d=await api('/auth/me');user=d.user;window.__csrf=d.csrf;const next=path==='/login'&&user.role==='employee'?safeVerifyReturn(new URLSearchParams(location.search).get('next')):null;location.replace(next||d.redirect);return}catch(e){if(e.status===403){location.href='/login';return}}
  authPage(path==='/signup');return;
 }
 if(path==='/pending'){location.replace('/login');return}
 if(path==='/employee/verify'){
  const returnPath=safeVerifyReturn(path+location.hash);
  if(!returnPath){employeeVerifyPage('');return}
  try{const d=await api('/auth/me');user=d.user;window.__csrf=d.csrf;if(user.role!=='employee'){location.replace(user.role==='admin'?'/admin':'/login');return}if(user.status!=='approved'){location.replace('/login');return}}
  catch{sessionStorage.setItem('fp_pending_verify',returnPath);location.replace('/login');return}
  const token=new URLSearchParams(location.hash.slice(1)).get('t');await employeeVerifyPage(token);return;
 }
 if(path.startsWith('/admin')||path.startsWith('/employee')){
  try{const d=await api('/auth/me');user=d.user;window.__csrf=d.csrf;if(!d.user||d.user.status!=='approved'){location.replace(d.redirect||'/login');return}const admin=path.startsWith('/admin');if(admin&&user.role!=='admin'||!admin&&user.role!=='employee'){location.replace(user.role==='admin'?'/admin':'/employee');return}}
  catch{location.replace('/login');return}
  const titles={'/admin':'대시보드','/admin/employees':'직원 관리','/admin/scanner':'기존 QR 스캐너','/admin/devices':'QR 단말기 관리','/admin/attendance':'근태 출석부','/admin/schedules':'근무 일정','/admin/statistics':'근태 통계','/admin/settings':'환경설정','/employee':'내 대시보드','/employee/attendance':'내 근태 기록','/employee/profile':'내 정보'};
  const title=titles[path];if(!title){staticError('요청한 페이지를 찾을 수 없습니다.');return}
  const view=shell(path,title);
  if(path==='/admin')loadAdminHome(view);else if(path==='/admin/employees')employees(view);else if(path==='/admin/scanner')scanner(view);else if(path==='/admin/devices')devicesPage(view);else if(path==='/admin/attendance')attendance(view,new URLSearchParams(location.search).get('employee')||'');else if(path==='/admin/schedules')schedules(view);else if(path==='/admin/statistics')statistics(view);else if(path==='/admin/settings')settings(view);else if(path==='/employee')employeeHome(view);else if(path==='/employee/attendance')employeeAttendance(view);else profile(view);
  return;
 }
 staticError('페이지를 찾을 수 없습니다.');
}
document.addEventListener('click',e=>{const x=e.target.closest('[data-static]');if(x){e.preventDefault();toast(x.dataset.static)}});window.addEventListener('error',e=>{if(e.target instanceof HTMLScriptElement||e.target instanceof HTMLLinkElement){const app=$('#app');if(app?.querySelector('.boot'))staticError('정적 리소스를 불러오지 못했습니다. 페이지를 새로고침해 주세요.')}else if($('#app')?.querySelector('.boot'))staticError('페이지 초기화 중 오류가 발생했습니다. 새로고침해 주세요.')},true);window.addEventListener('unhandledrejection',e=>{toast(e.reason?.message||'요청 처리 중 문제가 발생했습니다.');e.preventDefault()});try{boot().catch(error=>staticError(error?.message||'페이지 초기화 중 오류가 발생했습니다. 새로고침해 주세요.'))}catch(error){staticError(error?.message||'페이지 초기화 중 오류가 발생했습니다. 새로고침해 주세요.')}